} else if (hour > 17) {
  enrichedContext += "Time Context: Evening - consider next-day preparation. ";
  researchPerformed = true;
}

// 5. Default if no context was added
if (!researchPerformed) {
  enrichedContext = "No specific context found. This appears to be a new conversation.";
}

// Return the enriched context
return {
  json: {
    ...inputData,
    context: enrichedContext,
    researchPerformed: researchPerformed,
    researchTimestamp: new Date().toISOString()
  }
};

const out = [];

for (const item of items) {
  const msg = { ...item.json };
  const text = (msg.text || '').toLowerCase();
  const channel = (msg.channel_resolved || '').toLowerCase();
  const isBot = !!msg.event?.bot_id;

  // NEW: Message Complexity Detection
  const messageLength = text.length;
  const isSimple = 
    messageLength < 100 && 
    !text.match(/\?/) &&
    !text.match(/\b(research|analyze|plan|strategy|help with|create|build|develop|review)\b/i) &&
    !text.match(/\b(how|what|when|where|why|which)\b/i);

  msg.messageComplexity = isSimple ? 'simple' : 'complex';

  // Existing routing logic
  let initial = null;
  let replyN = false;

  // A) @mention wins
  for (const a of msg.agent_handles) {
    if (new RegExp(`@${a}\\b`, 'i').test(text)) {
      initial = a;
      replyN = true;
      break;
    }
  }
  // B) plain-word mention (humans only)
  if (!initial && !isBot) {
    for (const a of msg.agent_handles) {
      if (new RegExp(`\\b${a}\\b`, 'i').test(text)) {
        initial = a;
        replyN = true;
        break;
      }
    }
  }
  // C) 1:1 slug fallback (humans only)
  if (!initial && !isBot) {
    for (const a of msg.agent_handles) {
      if (channel.includes(a)) {
        initial = a;
        replyN = true;
        break;
      }
    }
  }

  msg.initial_TargetRecipient = initial;
  msg.replyNeeded = replyN;

  out.push({ json: msg });
}

return out;

