// Format Simple Messages - Dynamic with Target
const inputMsg = $json;

// Get the target agent config if target exists
const targetHandle = inputMsg.initial_TargetRecipient;
let targets = [];

if (targetHandle && inputMsg.agents_config) {
  const agentConfig = inputMsg.agents_config.find(agent => agent.handle === targetHandle);

  if (agentConfig) {
    targets.push({
      agentConfig: agentConfig,
      prompt: `You are ${agentConfig.realName}, ${agentConfig.role}. Message for responding: ${inputMsg.text}`
    });
  }
}

// Format in expected structure
return {
  json: {
    inputData: {
      sender: inputMsg.user_resolved || inputMsg.user,
      initial_TargetRecipient: inputMsg.initial_TargetRecipient,
      resolved_channel: inputMsg.channel_resolved,
      channel_id: inputMsg.channel,
      thread_id: "thread_von_ellis_" + inputMsg.channel_resolved || inputMsg.ts || "",
      thread_ts: inputMsg.ts || "",
      text: inputMsg.combined_message_text,
      context: "simple_message",
      channelType: inputMsg.channelType
    },
    targets: targets,
    generalAnswer: null
  }
